589:     function updateColorOutput(hex, brightnessPercent) {
590:         const adjustedHex = applyBrightness(hex, brightnessPercent);
591: 
592:         document.getElementById('live-color-preview').style.backgroundColor = adjustedHex;
593:         document.getElementById('selected-color-name').innerText = currentColorName;
594:         document.getElementById('selected-color-hex').innerText = "HEX: " + adjustedHex.toUpperCase();
