598:         document.getElementById('color_name_input').value = currentColorName + " (" + brightnessPercent + "%)";
599:     }
600: 
601:     function applyBrightness(hex, percent) {
602:         let num = parseInt(hex.replace("#", ""), 16),
603:             amt = Math.round(2.55 * (percent - 100)),
604:             R = (num >> 16) + amt,
605:             G = (num >> 8 & 0x00FF) + amt,
606:             B = (num & 0x0000FF) + amt;
607: 
608:         return "#" + (0x1000000 + 
609:             (R < 255 ? (R < 1 ? 0 : R) : 255) * 0x10000 + 
610:             (G < 255 ? (G < 1 ? 0 : G) : 255) * 0x100 + 
611:             (B < 255 ? (B < 1 ? 0 : B) : 255)
612:         ).toString(16).slice(1);
613:     }
